265	    new_pcb->user_stack_base = USER_STACK_ADDR;
266	    new_pcb->preempt_count = 0;
267	    init_list_head(&new_pcb->wait_list);
268	    init_list_head(&new_pcb->timer.list);
269	    new_pcb->binsem_num = 0;
270	    new_pcb->pid = process_id++;
271	    new_pcb->type = USER_PROCESS;
272	    new_pcb->status = TASK_READY;
273	    new_pcb->mode = mode;
274	    new_pcb->priority = 1;
275	    new_pcb->ready_tick = get_ticks();
276	    /* a child may run wherever its parent was allowed to run */
277	    new_pcb->mask = current_running[cpu_id]->mask;
278	    if (new_pcb->mask == 0) {
279	        new_pcb->mask = (1UL << NR_CPUS) - 1;
280	    }
281	    new_pcb->cpu_id = cpu_id;
282	    new_pcb->cursor_x = 1;
283	    new_pcb->cursor_y = 1;
284	
285	    uintptr_t entry = load_elf(binary, (unsigned)length,
286	                               (uintptr_t)new_pcb->pgdir, alloc_page_helper);
287	    uintptr_t argv_va = init_user_stack(new_pcb, &argc, argv);
288	
289	    init_pcb_stack(new_pcb->kernel_sp, new_pcb->user_sp, entry,
290	                   new_pcb, argc, argv_va);
291	    list_add_tail(&new_pcb->list, &ready_queue);
292	
293	    pid_t new_pid = new_pcb->pid;
294	    disable_sum();
295	    enable_preempt();
296	    return new_pid;
297	}
