299	/* Give up every binary semaphore `task` still holds and hand each of them to
300	 * the next waiter, so that nobody stays blocked on a dead process. */
301	static void release_binsem(pcb_t *task)
302	{
303	    while (task->binsem_num > 0) {
304	        int id = task->binsem_id[--task->binsem_num];
305	        binsem_node_t *node = &binsem_nodes[id];
306	
307	        node->sem++;
308	        if (node->sem <= 0 && !list_empty(&node->block_queue)) {
309	            list_node_t *heir_node = node->block_queue.next;
310	            pcb_t *heir = list_entry(heir_node, pcb_t, list);
311	            heir->binsem_id[heir->binsem_num++] = id;
312	            do_unblock(heir_node);
313	        }
314	    }
315	}
316	
317	/*
318	 * A task that dies while queued on a binary semaphore has already spent the
319	 * `sem--` of its pending acquire.  Give that count back, otherwise the next
320	 * release would believe somebody is still waiting and hand the lock to the
321	 * head of an empty queue.
322	 */
323	static void abandon_binsem_wait(pcb_t *task)
324	{
325	    for (int i = 0; i < BINSEM_NUMBER; i++) {
326	        binsem_node_t *node = &binsem_nodes[i];
327	        list_node_t *p;
328	        for (p = node->block_queue.next; p != &node->block_queue; p = p->next) {
329	            if (p == &task->list) {
330	                list_del(p);
331	                node->sem++;
332	                return;
333	            }
334	        }
335	    }
336	}
337	
338	/* Common part of exiting and being killed: hand back the semaphores, wake
339	 * everybody who waits for this task and disarm its sleep timer. */
340	static void release_resources(pcb_t *task)
341	{
342	    release_binsem(task);
343	    abandon_binsem_wait(task);
344	
345	    while (!list_empty(&task->wait_list)) {
346	        do_unblock(task->wait_list.next);
347	    }
348	
349	    /* a sleeping task may still have an armed timer */
350	    list_del(&task->timer.list);
351	}
352	
353	/*
354	 * Destroy `task` completely: give back everything it holds, throw away its
355	 * address space and mark the pcb.  The kernel stack survives a little longer,
356	 * because a task that has just stopped running is still standing on it: it is
357	 * released either by the parent in do_waitpid() or by the idle task of core 0.
358	 */
359	static void destroy_task(pcb_t *task, int still_on_kernel_stack)
360	{
361	    release_resources(task);
362	
363	    free_process_user_page(task->pgdir);
364	    task->pgdir = (PTE*)PGDIR_PA;
365	
366	    list_del(&task->list);
367	
368	    if (task->mode == ENTER_ZOMBIE_ON_EXIT) {
369	        /* the parent reaps us in do_waitpid() */
370	        task->status = TASK_ZOMBIE;
371	    } else {
372	        task->status = TASK_EXITED;
373	        if (still_on_kernel_stack) {
374	            /* it is still unwinding out of the kernel: let the idle task of
375	             * core 0 have it only after the next scheduling round */
376	            pending_reap[cpu_id] = task;
377	        } else {
378	            list_add_tail(&task->list, &kernel_pcb[0].wait_list);
379	        }
380	    }
381	}
382	
383	void do_exit()
384	{
385	    disable_preempt();
386	    pcb_t *cur = current_running[cpu_id];
387	
388	    /* We still run in this address space and on this kernel stack, so the
389	     * teardown has to wait until scheduler() has switched away from us. */
390	    list_del(&cur->list);
391	    pending_kill[cpu_id] = cur;
392	    scheduler();
393	
394	    enable_preempt();
395	}
