462	/*
463	 * A blocked process can only be resumed in user mode, so waitpid cannot
464	 * simply continue where it left off.  Instead the caller is blocked on the
465	 * child's wait list and `sepc` is rewound onto the `ecall`, so once the child
466	 * exits the system call is executed again -- this time finding the child
467	 * gone (or a zombie ready to be reaped).  The return value has to be `pid`
468	 * in that case because handle_syscall() writes it back into a0, which is the
469	 * very argument the retried `ecall` will pick up.
470	 */
471	int do_waitpid(pid_t pid, reg_t ignore1, reg_t ignore2, reg_t ignore3, regs_context_t *regs)
472	{
473	    disable_preempt();
474	
475	    pcb_t *child = find_pcb(pid);
476	
477	    if (child == NULL) {
478	        /* already gone and cleaned up */
479	        enable_preempt();
480	        return 0;
481	    }
482	
483	    if (child->status == TASK_ZOMBIE || child->status == TASK_EXITED) {
484	        /* reap it: release the kernel stack and free the pcb slot */
485	        free_user_page(kva2pa(child->kernel_stack_base - PAGE_SIZE));
486	        list_del(&child->list);
487	        child->status = TASK_EXITED;
488	        child->pid = -1;
489	        enable_preempt();
490	        return 1;
491	    }
492	
493	    /* still alive: sleep on it and retry the system call when woken up */
494	    regs->sepc = regs->sepc - 4;
495	    do_block(&current_running[cpu_id]->list, &child->wait_list);
496	    scheduler();
497	
498	    enable_preempt();
499	    return pid;
500	}
