670	// block the pcb task into the block queue
671	void do_block(list_node_t *pcb_node, list_head *queue)
672	{
673	    list_del(pcb_node);
674	    list_add_tail(pcb_node, queue);
675	    list_entry(pcb_node, pcb_t, list)->status = TASK_BLOCKED;
676	}
