678	// unblock the `pcb` from the block queue
679	void do_unblock(list_node_t *pcb_node)
680	{
681	    list_del(pcb_node);
682	    list_add_tail(pcb_node, &ready_queue);
683	    list_entry(pcb_node, pcb_t, list)->status = TASK_READY;
684	    list_entry(pcb_node, pcb_t, list)->ready_tick = get_ticks();
685	}
