687	/*
688	 * Pick the ready task with the highest effective priority that is allowed to
689	 * run on this hart.  The effective priority is the static priority plus an
690	 * ageing bonus of one point per scheduling tick already spent waiting, so a
691	 * low priority task cannot starve.  Ties go to the task that has been in the
692	 * queue longest, which keeps equal priorities round-robin.
693	 */
694	list_node_t* max_priority_node(void)
695	{
696	    list_node_t *node;
697	    list_node_t *max_node = NULL;
698	    uint64_t max_priority = 0;
699	    uint64_t current_tick = get_ticks();
700	
701	    for (node = ready_queue.next; node != &ready_queue; node = node->next) {
702	        pcb_t *task = list_entry(node, pcb_t, list);
703	        uint64_t waited_tick = 0;
704	        uint64_t priority;
705	
706	        /* cpu affinity */
707	        if (!(task->mask & (1UL << cpu_id))) {
708	            continue;
709	        }
710	
711	        if (current_tick > task->ready_tick) {
712	            waited_tick = current_tick - task->ready_tick;
713	        }
714	        priority = (uint64_t)task->priority;
715	        if (timer_interval != 0) {
716	            priority += waited_tick / timer_interval;
717	        }
718	
719	        if (max_node == NULL || priority > max_priority) {
720	            max_node = node;
721	            max_priority = priority;
722	        }
723	    }
724	
725	    return max_node;
726	}

