   123	#define MIN(a, b) ((a) < (b) ? (a) : (b))
   124	
   125	static inline int is_elf_format(unsigned char *binary)
   126	{
   127	    Elf64_Ehdr *ehdr = (Elf64_Ehdr *)binary;
   128	
   129	    if (ehdr->e_ident[0] == EI_MAG0 &&
   130	        ehdr->e_ident[1] == EI_MAG1 &&
   131	        ehdr->e_ident[2] == EI_MAG2 &&
   132	        ehdr->e_ident[3] == EI_MAG3) {
   133	        return 0;
   134	    }
   135	
   136	    return 1;
   137	}
   138	
   139	/* prepare_page_for_kva should return a kernel virtual address */
   140	static inline uintptr_t load_elf(
   141	    unsigned char elf_binary[], unsigned length, uintptr_t pgdir,
   142	    uintptr_t (*prepare_page_for_va)(uintptr_t va, uintptr_t pgdir))
   143	{
   144	    Elf64_Ehdr *ehdr = (Elf64_Ehdr *)elf_binary;
   145	    Elf64_Phdr *phdr = NULL;
   146	    /* As a loader, we just care about segment,
   147	     * so we just parse program headers.
   148	     */
   149	    unsigned char *ptr_ph_table = NULL;
   150	    Elf64_Half ph_entry_count;
   151	    Elf64_Half ph_entry_size;
   152	    int i = 0;
   153	
   154	    // check whether `binary` is a ELF file.
   155	    if (length < 4 || !is_elf_format(elf_binary)) {
   156	        return 0;  // return NULL when error!
   157	    }
   158	
   159	    ptr_ph_table   = elf_binary + ehdr->e_phoff;
   160	    ph_entry_count = ehdr->e_phnum;
   161	    ph_entry_size  = ehdr->e_phentsize;
   162	
   163	    while (ph_entry_count--) {
   164	        phdr = (Elf64_Phdr *)ptr_ph_table;
   165	
   166	        if (phdr->p_type == PT_LOAD) {
   167	            /* TODO: */
   168	            for (i = 0; i < phdr->p_memsz; i += NORMAL_PAGE_SIZE) {
   169	                if (i < phdr->p_filesz) {
   170	                    unsigned char *bytes_of_page = (unsigned char *)prepare_page_for_va((uintptr_t)(phdr->p_vaddr + i), pgdir);
   171	                    memcpy(bytes_of_page, elf_binary + phdr->p_offset + i, MIN(phdr->p_filesz - i, NORMAL_PAGE_SIZE));
   172	                    if (phdr->p_filesz - i < NORMAL_PAGE_SIZE) {
   173	                        for (int j = phdr->p_filesz % NORMAL_PAGE_SIZE; j < NORMAL_PAGE_SIZE; ++j) {
   174	                            bytes_of_page[j] = 0;
   175	                        }
   176	                    }
   177	                } 
   178	                else {
   179	                    long *bytes_of_page = (long *)prepare_page_for_va((uintptr_t)(phdr->p_vaddr + i), pgdir);
   180	                    for (int j = 0; j < NORMAL_PAGE_SIZE / sizeof(long); ++j) {
   181	                        bytes_of_page[j] = 0;
   182	                    }
   183	                }
   184	            }
   185	        }
   186	
   187	        ptr_ph_table += ph_entry_size;
   188	    }
   189	
   190	    return ehdr->e_entry;
   191	}
