148	    int VPN2 = (va >> VPN2_SHIFT) & VPN_MASK;
149	    int VPN1 = (va >> VPN1_SHIFT) & VPN_MASK;
150	    int VPN0 = (va >> VPN0_SHIFT) & VPN_MASK;
