152	    PTE* second_level_pgdir = (PTE*)get_pa((uintptr_t)*((PTE*)pgdir_kva + VPN2));
153	    second_level_pgdir = (PTE*)pa2kva((uintptr_t)second_level_pgdir);
154	    PTE* last_level_pgdir = (PTE*)get_pa((uintptr_t)*((PTE*)second_level_pgdir + VPN1));
155	    last_level_pgdir = (PTE*)pa2kva((uintptr_t)last_level_pgdir);
156	    uintptr_t pa = get_pa((uintptr_t)*((PTE*)last_level_pgdir + VPN0)) | (va & PAGE_OFFSET_MASK);
